from copy import deepcopy
import re


class GridRoom:
    def __init__(self, width, height):
        if isinstance(width, bool) or not isinstance(width, int) or width < 1:
            raise ValueError("width must be a positive integer")
        if isinstance(height, bool) or not isinstance(height, int) or height < 1:
            raise ValueError("height must be a positive integer")
        self._width = width
        self._height = height
        self._next_id = 1
        self._participants = {}

    def join(self, name, appearance):
        if not isinstance(name, str) or not name:
            raise ValueError("name must be a non-empty string")
        if not isinstance(appearance, dict):
            raise TypeError("appearance must be a dictionary")
        participant_id = self._next_id
        self._next_id += 1
        self._participants[participant_id] = {
            "id": participant_id,
            "name": name,
            "appearance": deepcopy(appearance),
            "position": ((participant_id * 3) % self._width, (participant_id * 5) % self._height),
            "color": ((participant_id * 53) % 200, (participant_id * 97) % 200, (participant_id * 149) % 200),
        }
        return participant_id

    def execute(self, participant_id, command):
        if participant_id not in self._participants:
            raise KeyError(participant_id)
        if not isinstance(command, str):
            raise ValueError("command must be a string")
        if command == "whoami":
            return participant_id
        if command == "roster":
            return self.snapshot()
        match = re.fullmatch(r"place ([0-9]+) ([0-9]+)", command)
        if match is not None:
            x = int(match.group(1), 10)
            y = int(match.group(2), 10)
            if not (0 <= x <= self._width and 0 <= y <= self._height):
                raise ValueError("coordinates are outside the room")
            self._participants[participant_id]["position"] = (x, y)
            return x, y
        raise ValueError("unknown or malformed command")

    def leave(self, participant_id):
        return self._participants.pop(participant_id, None) is not None

    def snapshot(self):
        return [deepcopy(self._participants[item_id]) for item_id in sorted(self._participants)]

